mapper.select:
SELECT COALESCE(max(version), 0) + 1
FROM platform_skill_versions
WHERE skill_id = #{skillId}

mapper.update:
UPDATE platform_skill_versions
SET published_at = COALESCE(published_at, now())
WHERE id = #{versionId}

UPDATE platform_skill_versions
SET package_key = #{packageKey}, package_sha256 = #{packageSha256},
    package_size_bytes = #{packageSizeBytes},
    manifest = #{manifest, typeHandler=com.kross.support.JsonbTypeHandler}
WHERE id = #{versionId}

UPDATE credential_handles SET name = COALESCE(#{name}, name), status = COALESCE(#{status}, status),
  metadata = COALESCE(#{metadata, typeHandler=com.kross.support.JsonbTypeHandler}, metadata), updated_at = now()
WHERE id = #{id}
